def apply_latex_normalize_action(text: str, action: str = "full") -> str:
    """Áp dụng một bước chuẩn hóa LaTeX (không AI)."""
    key = clean(action) or "full"
    fn = LATEX_NORMALIZE_ACTIONS.get(key) or normalize_latex_text
    return fn(clean(text))


def apply_latex_normalize_with_selection(
    text: str,
    action: str,
    selection: Optional[Dict[str, Any]] = None,
) -> str:
    """Chuẩn hóa cả ô hoặc chỉ đoạn được bôi đen."""
    if not selection:
        return apply_latex_normalize_action(text, action)
    full = clean(selection.get("full") or text)
    try:
        start = max(0, int(selection.get("start", 0)))
        end = max(start, int(selection.get("end", 0)))
    except (TypeError, ValueError):
        return apply_latex_normalize_action(text, action)
    if end <= start:
        return apply_latex_normalize_action(full, action)
    segment = full[start:end]
    fixed_seg = apply_latex_normalize_action(segment, action)
    return full[:start] + fixed_seg + full[end:]


def _fix_bare_trig_latex(t: str) -> str:
    if not t:
        return t
    t = re.sub(r"\(sin\^2\)", r"\\sin^2", t, flags=re.I)
    t = re.sub(r"\(cos\^2\)", r"\\cos^2", t, flags=re.I)
    t = re.sub(r"\(tan\^2\)", r"\\tan^2", t, flags=re.I)
    t = re.sub(r"\(cot\^2\)", r"\\cot^2", t, flags=re.I)
    t = re.sub(r"\((sin|cos|tan|cot)\^2", r"(\\\1^2", t, flags=re.I)
    t = re.sub(r"([+\-])\s*(sin|cos|tan|cot)\^2", r"\1\\\2^2", t, flags=re.I)
    t = re.sub(r"\{\\?(cos|sin|tan|cot)\s*\^2\s*\}2\\alpha", r"\\\1^2\\alpha", t, flags=re.I)
    t = re.sub(r"\{\s*\\?(sin|cos|tan|cot)\s+\^?\s*2\s*\}", r"\\\1^2", t, flags=re.I)
    t = re.sub(r"\\(cos|sin|tan|cot)\^22\\alpha", r"\\\1^2\\alpha", t, flags=re.I)
    return t


def _space_around_inline_math_in_prose(t: str) -> str:
    """Thêm khoảng trắng quanh $...$ trong câu tiếng Việt; gỡ $•$ lỗi."""
    if not t:
        return t
    t = re.sub(r"\$\s*•\s*\$", "•", t)
    if "$" not in t:
        return t
    out: List[str] = []
    i, n = 0, len(t)
    while i < n:
        if t[i] != "$":
            d = t.find("$", i)
            if d < 0:
                out.append(t[i:])
                break
            out.append(t[i:d])
            i = d
            continue
        # Xử lý $$ display math — giữ nguyên, không thêm khoảng trắng
        if i + 1 < n and t[i + 1] == "$":
            end = t.find("$$", i + 2)
            if end >= 0:
                out.append(t[i : end + 2])
                i = end + 2
            else:
                out.append(t[i:])
                break
            continue
        d = t.find("$", i + 1)
        if d < 0:
            out.append(t[i:])
            break
        inner = t[i + 1 : d].strip()
        chunk = f"${inner}$"
        if out and out[-1] and not out[-1][-1].isspace() and out[-1][-1] not in "«(":
            out.append(" ")
        out.append(chunk)
        i = d + 1
        if i < n and not t[i].isspace() and t[i] not in "$«»,.;:!?)]":
            out.append(" ")
    return "".join(out)


def _wrap_vn_context_numbers_in_math(t: str) -> str:
    """Bọc số sau tháng/năm/ngày: «tháng 6» → «tháng $6$» (chỉ ngoài khối $)."""
    if not t:
        return t

    def _plain(seg: str) -> str:
        return re.sub(
            r"\b(tháng|thang|năm|nam|ngày|ngay)\s+(\d{1,4})\b",
            r"\1 $\2$",
            seg,
            flags=re.I,
        )

    return _latex_map_segments(t, on_plain=_plain)


def _looks_like_bare_latex_chunk(s: str) -> bool:
    s = clean(s)
    if not s:
        return False
    if _has_vietnamese_text(s):
        return False
    if re.search(r"\\(?:begin|end|item)\b", s, re.I):
        return False
    if re.search(r"\\begin\s*\{", s, re.I):
        return False
    if "\\" in s:
        return True
    if re.search(r"\((?:sin|cos|tan|cot)", s, re.I):
        return True
    if re.search(r"[\^_=]", s) and re.search(r"[A-Za-z0-9]", s):
        return not re.search(r"[À-ỹĐđ]{3,}", s)
    return False


def _parse_latex_command_at(s: str, pos: int) -> int:
    """Đọc một lệnh \\cmd{...} tại pos (pos trỏ vào \\). Trả về index sau đoạn đã đọc."""
    n = len(s)
    if pos >= n or s[pos] != "\\":
        return pos
    i = pos + 1
    while i < n and s[i].isalpha():
        i += 1
    while i < n:
        if s[i] == "{":
            got = _read_latex_braced_content(s, i)
            if not got:
                break
            i = got[1] + 1
        elif s[i] in "^_":
            i += 1
            if i < n and s[i] == "{":
                got = _read_latex_braced_content(s, i)
                i = (got[1] + 1) if got else i
            elif i < n:
                i += 1
        else:
            break
    return i


def _find_bare_latex_span(s: str, start: int) -> tuple[int, int]:
    """Tìm đoạn LaTeX chưa có $ bắt đầu từ start. Trả (start, end) hoặc (start, start)."""
    n = len(s)
    i = start
    while i < n and s[i].isspace():
        i += 1
    if i >= n:
        return start, start
    if s[i] == "$":
        return start, start

    beg = i
    if s[i] == "\\":
        if i + 1 < n and s[i + 1] == "\\":
            return start, start
        end = i
        while end < n:
            if s[end] == "\\":
                end = _parse_latex_command_at(s, end)
            elif s[end] in "^_":
                end += 1
                if end < n and s[end] == "{":
                    got = _read_latex_braced_content(s, end)
                    end = (got[1] + 1) if got else end
                elif end < n:
                    end += 1
            elif s[end] in "+-=<>*/|·":
                end += 1
                while end < n and s[end].isspace():
                    end += 1
            elif s[end] in "(),.;":
                if s[end] in "(),":
                    end += 1
                    continue
                break
            elif s[end].isalnum():
                j = end
                while j < n and re.match(r"[A-Za-z0-9+\-*/.,;|()]", s[j]):
                    j += 1
                if j == end:
                    break
                end = j
            else:
                break
            chunk = s[beg:end]
            if re.search(r"[À-ỹĐđ]{3,}", chunk):
                m = re.search(r"[À-ỹĐđ]{3,}", chunk)
                if m:
                    end = beg + m.start()
                break
        if end > beg and _looks_like_bare_latex_chunk(s[beg:end]):
            return beg, end
        return start, start

    if s[i] == "(":
        depth = 0
        j = i
        while j < n:
            if s[j] == "(":
                depth += 1
            elif s[j] == ")":
                depth -= 1
                if depth == 0:
                    inner = s[i + 1 : j]
                    if (
                        _looks_like_bare_latex_chunk(inner)
                        or "\\" in inner
                        or re.search(r"(?:sin|cos|tan|cot)\^?", inner, re.I)
                    ):
                        return i, j + 1
                    return start, start
            j += 1
    return start, start


def _latex_plain_linebreaks(seg: str) -> str:
    """\\\\ / \\ ngoài khối $...$ → xuống dòng (lời giải Word/Sheet)."""
    if not seg or "\\" not in seg:
        return seg
    return re.sub(r"\\{2,}\s*", "\n", seg)


def _wrap_bare_latex_in_plain(seg: str) -> str:
    """Bọc từng đoạn \\frac, \\sqrt, (sin^2)… trong văn bản thường bằng $...$."""
    seg = _latex_plain_linebreaks(seg)
    if not seg or (
        "\\" not in seg
        and not re.search(r"[\^_=]|\((?:sin|cos|tan|cot)", seg, re.I)
    ):
        return seg
    seg = _fix_bare_trig_latex(seg)
    out: list[str] = []
    i, n = 0, len(seg)
    while i < n:
        if seg[i] == "$":
            d = seg.find("$", i + 1)
            if d < 0:
                out.append(seg[i:])
                break
            out.append(seg[i : d + 1])
            i = d + 1
            continue
        beg, end = _find_bare_latex_span(seg, i)
        if end > beg:
            chunk = seg[beg:end].strip()
            out.append(seg[i:beg])
            out.append(f"${chunk}$")
            i = end
            continue
        nxt = n
        for marker in ("\\", "(", "^", "_", "="):
            p = seg.find(marker, i + 1)
            if p >= 0:
                nxt = min(nxt, p)
        out.append(seg[i:nxt])
        i = nxt
    result = "".join(out)
    return _merge_adjacent_inline_math(result)


def _wrap_bare_latex_math(t: str) -> str:
    if not t or "$" in t:
        return t
    if _is_latex_prose_content(t):
        return t
    if not (
        re.search(r"\\[a-zA-Z]", t)
        or re.search(r"[\^_=]", t)
        or re.search(r"\((?:sin|cos|tan|cot)", t, re.I)
    ):
        return t
    t = _fix_bare_trig_latex(t)
    return f"${t}$"


def _latex_action_add_dollar_math(t: str) -> str:
    return _latex_map_segments(t, on_plain=_wrap_bare_latex_in_plain)


def _latex_action_add_dollar_suitable(t: str) -> str:
    t = _latex_action_add_dollar_math(t)
    t = _latex_action_add_dollar_points(t)
    return _fix_surplus_dollar_signs(t)


LATEX_NORMALIZE_ACTIONS["add_dollar_math"] = _latex_action_add_dollar_math
LATEX_NORMALIZE_ACTIONS["add_dollar_suitable"] = _latex_action_add_dollar_suitable


def _fix_broken_latex_patterns(t: str) -> str:
    """Sửa lỗi LaTeX phổ biến từ Word/Sheet (ngoài khối $...$)."""
    if not t:
        return t

    # ── 0. Áp dụng bên trong từng khối $...$ ──────────────────────────────
    def _fix_inside_math(inner: str) -> str:
        prev = None
        while prev != inner:
            prev = inner
            # {{X}_{n}} → X_{n}
            inner = re.sub(r"\{\{([A-Za-z])\}(_\{[^{}]+\})\}", r"\1\2", inner)
            inner = re.sub(r"\{\{([A-Za-z])\}(\^\{[^{}]+\})\}", r"\1\2", inner)
            inner = re.sub(r"\{\{([A-Za-z0-9])\}\}", r"\1", inner)
            inner = re.sub(r"\{\{([^{}]+)\}(_\{[^{}]+\})\}", r"{\1}\2", inner)
            inner = re.sub(r"\{\{([^{}]+)\}(\^\{[^{}]+\})\}", r"{\1}\2", inner)
            inner = re.sub(r"\{([<>=!±×÷])\}", r"\1", inner)
            inner = re.sub(r"\{(\\(?:leq|geq|neq|approx|pm|cdot|times|div|Rightarrow|rightarrow|Leftrightarrow))\}", r"\1", inner)

        # ── Backslash + space trước đơn vị: $10\ kg$ → $10\,\text{kg}$ ──────
        # Đơn vị phức hợp phải match TRƯỚC đơn giản (km/h trước km)
        _UNITS_RE = (
            r"km/h|m/s\^2|m/s|"            # vận tốc/gia tốc trước
            r"kg|mg|kJ|kN|kW|kV|kPa|kHz|" # kilo- trước ký tự đơn
            r"MJ|MN|MW|MPa|MHz|"           # mega-
            r"ms|mA|mV|mH|uF|pF|"         # mili/micro
            r"g|m|t|s|h|"                  # đơn giản
            r"km|cm|mm|nm|um|min|"
            r"N|J|W|Pa|K|A|V|C|F|H|T|Wb|"
            r"Hz|mol|cal|kcal|rpm|rad|atm"
        )
        inner = re.sub(
            r"\\ (" + _UNITS_RE + r")\b",
            lambda m: r"\,\text{" + m.group(1) + r"}",
            inner,
        )
        # $\J$ $\W$ v.v. — \UpperCase không phải lệnh LaTeX hợp lệ
        _VALID_UPPER = {
            "Rightarrow","Leftrightarrow","Longrightarrow","Longleftrightarrow",
            "Delta","Sigma","Omega","Gamma","Lambda","Theta","Pi","Phi","Psi",
            "Xi","Upsilon","Alpha","Beta","Epsilon","Zeta","Eta","Iota","Kappa",
            "Mu","Nu","Rho","Tau","Chi","Re","Im",
            "left","right","Big","Bigg","mathbb","mathcal","mathbf","mathit",
            "boldsymbol","vec","hat","bar","tilde","dot","ddot","breve",
            "check","acute","grave","widehat","widetilde","overline","underline",
        }
        def _fix_bad_upper_cmd(m: re.Match) -> str:
            cmd = m.group(1)
            if cmd in _VALID_UPPER:
                return m.group(0)
            return r"\,\text{" + cmd + r"}"
        inner = re.sub(r"\\([A-Z][A-Za-z]{0,4})\b(?!\{)", _fix_bad_upper_cmd, inner)

        return inner

    t = re.sub(r"\$([^$\n]+)\$", lambda m: "$" + _fix_inside_math(m.group(1)) + "$", t)

    # ── 0b. Sửa \begin{array}{l} thiếu \\ ─────────────────────────────────
    # VD: \begin{array}{l} p.V=const {{p}_{1}>{p}_{2} \end{array}
    # → \begin{array}{l} p.V=\text{const} \\ p_1>p_2 \end{array}
    def _fix_array_rows(m: re.Match) -> str:
        spec = m.group(1)   # {l} hoặc {ll} v.v.
        inner = m.group(2)
        # Nếu không có \\ giữa các phần tử nhưng có nhiều biểu thức
        if r"\\" not in inner and "\n" not in inner:
            # Thử tách theo các điểm tự nhiên: sau dấu . trước \p hoặc ký tự hoa
            inner = re.sub(r"(\S)\s+(\\?[A-Z\\])", r"\1 \\\\ \2", inner, count=3)
        return r"\begin{array}" + spec + inner + r"\end{array}"
    t = re.sub(r"\\begin\{array\}(\{[^}]+\})([\s\S]*?)\\end\{array\}", _fix_array_rows, t)

    # ── 0c. } dư ở cuối khối $ (Word cắt mất \dfrac vế phải) ──────────────
    # VD: $\dfrac{p_1}{p_2}=\dfrac{V_2}$  → bỏ qua, không thể đoán vế thiếu
    # Chỉ cảnh báo bằng cách normalize thôi, không sửa nội dung

    # ── 1. mathrm/mathbf/text thiếu backslash ──────────────────────────────
    t = re.sub(r"(?<!\\)\b(mathrm|mathbf|mathit|mathsf|mathnormal|text|textrm|operatorname)\s*\{", r"\\\1{", t)

    # ── 2. \(\begin{aligned) → $$\begin{aligned}…\end{aligned}$$ ───────────
    t = re.sub(r"\\?\\\(\s*\\begin\{aligned\)", r"$$\\begin{aligned}", t, flags=re.I)
    t = re.sub(r"\\end\{aligned\}\s*\.\s*\\?\)", r"\\end{aligned}.$$", t, flags=re.I)
    t = re.sub(r"\\end\{aligned\}\s*\\?\)", r"\\end{aligned}$$", t, flags=re.I)

    # ── 3. \newline bên trong aligned/array → \\ ───────────────────────────
    def _fix_env_newline(m: re.Match) -> str:
        env = m.group(1)
        inner = m.group(2)
        inner = re.sub(r"\\newline\b", r"\\\\", inner)
        return r"\begin{" + env + r"}" + inner + r"\end{" + env + r"}"
    t = re.sub(r"\\begin\{(aligned|array|cases|gather|multline)\}([\s\S]*?)\\end\{\1\}", _fix_env_newline, t)

    # ── 4. \tag{n} nằm ngoài $$ → đóng $$ trước ──────────────────────────
    t = re.sub(r"(\$\$[^$]*?\\tag\{[^}]+\})([^$])", r"\1$$\n\2", t, flags=re.S)

    # ── 5. $\cdot$ $\Rightarrow$ … đứng rời → bỏ $ bao ───────────────────
    for cmd in (r"\\cdot", r"\\Rightarrow", r"\\Leftrightarrow", r"\\rightarrow",
                r"\\to", r"\\ge", r"\\le", r"\\neq", r"\\approx"):
        t = re.sub(r"\$(" + cmd + r")\$", r"\1", t)

    # ── 6. Tag + text liền → thêm space ───────────────────────────────────
    t = re.sub(r"(\\tag\{[^}]+\})([A-ZÀÁÂÃÈÉÊÌÍÒÓÔÕÙÚĂĐĨŨƠƯẠ-ỹ])", r"\1 \2", t)

    # ── 7. \( standalone không cặp \) → $ ─────────────────────────────────
    def _fix_lone_paren(m: re.Match) -> str:
        if r"\)" in m.group(0).split("\n")[0][2:]:
            return m.group(0)
        return "$" + m.group(1)
    t = re.sub(r"\\\(([^$\n]*?)(\n|$)", _fix_lone_paren, t)

    # ── 8. Các lỗi cũ ─────────────────────────────────────────────────────
    t = re.sub(r"\\acute\{\\mathrm\{i\}\}", "í", t, flags=re.I)
    t = re.sub(
        r"\\text\{\s*([^}]*?)\s*\}\s*\\acute\{[^}]+\}\s*\\text\{\s*t\s*\}",
        r"\\text{\1ít}", t, flags=re.I,
    )
    t = re.sub(r"(\d+)\s*c\{\{?\s*m\s*\}\}?\^\{3\}", r"$\1\\,\\text{cm}^{3}$", t, flags=re.I)
    t = re.sub(r"\$\(\s*(\d+)\^\{([^{}]+)\}\}(Pa|kPa)\.?\s*\$", r"$\1^{\2}\\,\\text{\3}.$", t, flags=re.I)
    t = re.sub(r"\$(\d+)\^\{([^{}]+)\}\}(Pa|kPa)\.?\$", r"$\1^{\2}\\,\\text{\3}.$", t, flags=re.I)
    return t


def _normalize_question_latex_field(field: str, value: Any) -> str:
    v = clean(value)
    if not v:
        return ""
    if field == "DapAn" and not any(x in v for x in ("$", "\\", "{", "}")):
        return v
    if field in ("CauHoi", "A", "B", "C", "D", "LoiGiai", "DapAn", "SaiSo"):
        return normalize_latex_text(v)
    return v


def _normalize_question_latex_updates(
    updates: Dict[str, Any],
    q: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    out = dict(updates or {})
    for f in ("CauHoi", "A", "B", "C", "D", "LoiGiai", "DapAn", "SaiSo"):
        if f in out:
            out[f] = _normalize_question_latex_field(f, out.get(f))
    merged = dict(q or {})
    merged.update({k: clean(v) for k, v in out.items()})
    if "LoiGiai" in out and clean(out.get("LoiGiai")):
        dang = effective_dang(merged)
        if dang == "Đúng sai":
            fixed = normalize_ds_loigiai(out["LoiGiai"], merged)
            if fixed:
                out["LoiGiai"] = fixed
        elif dang == "Trắc nghiệm" and _loigiai_has_splittable_chunks(out["LoiGiai"]):
            fixed = normalize_tn_loigiai_abcd(out["LoiGiai"], merged)
            if fixed:
                out["LoiGiai"] = fixed
    return out


def stable_hash(text: str, n: int = 12) -> str:
    return hashlib.sha1(text.encode("utf-8", errors="ignore")).hexdigest()[:n].upper()


def now_str() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def parse_datetime_any(s: Any) -> Optional[datetime]:
    """Đọc ngày giờ từ Google Sheet: 30/05/2026 13:37, 2026-05-30, hoặc serial dạng text."""
    s = clean(s)
    if not s:
        return None
    # Nếu Google Sheet trả serial ngày dạng số, 1 tương ứng 1899-12-30.
    try:
        if re.fullmatch(r"\d+(?:\.\d+)?", s):
            base = datetime(1899, 12, 30)
            return base + timedelta(days=float(s))
    except Exception:
        pass
    fmts = [
        "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d",
        "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y",
        "%d-%m-%Y %H:%M:%S", "%d-%m-%Y %H:%M", "%d-%m-%Y",
    ]
    for fmt in fmts:
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    return None


def fmt_datetime(dt: datetime) -> str:
    return dt.strftime("%d/%m/%Y %H:%M:%S")


def expired_datetime(s: Any) -> bool:
    dt = parse_datetime_any(s)
    return bool(dt and datetime.now() > dt)


def parse_float_vn(s: Any) -> Optional[float]:
    s = clean(s).replace(" ", "")
    if not s:
        return None
    if "," in s and "." not in s:
        s = s.replace(",", ".")
    else:
        s = s.replace(",", "")
    m = re.search(r"[-+]?\d+(?:\.\d+)?", s)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def norm_letter(s: Any) -> str:
    s = clean(s).upper()
    m = re.search(r"[ABCD]", s)
    return m.group(0) if m else ""


def norm_dang_explain(s: Any) -> Tuple[str, str]:
    """Chuẩn hóa tên dạng câu, trả về (dang_chuan, ly_do).

    Dùng khi cần log lý do chuyển đổi (đọc file Word, LaTeX import, sync).
    Giá trị chuẩn: "Trắc nghiệm" | "Đúng sai" | "Trả lời ngắn" | "Tự luận"

    Ví dụ:
        norm_dang_explain("d/s")        → ("Đúng sai",    "alias 'd/s' → Đúng sai")
        norm_dang_explain("TN4")        → ("Trắc nghiệm", "alias 'tn4' → Trắc nghiệm")
        norm_dang_explain("MCQ_custom") → ("Trắc nghiệm", "⚠ không nhận ra 'MCQ_custom' → mặc định Trắc nghiệm")
    """
    raw = str(s or "").strip()
    if not raw:
        return "Trắc nghiệm", "trống → mặc định Trắc nghiệm"

    # Chuẩn hoá: bỏ dấu phân cách, lowercase, bỏ dấu tiếng Việt
    t = re.sub(r"[/\\|.]+", " ", raw)
    k = key_norm(t)
    k2 = k.replace(" ", "")

    # ── ĐÚng SAI ─────────────────────────────────────────────────────────────
    _DS_PHRASES = ["dung sai", "true false", "truefalse", "dungsai"]
    _DS_EXACT   = {"ds", "tf", "d/s", "dungsai", "truefalse", "t/f", "ds4", "dsai"}
    for alias in _DS_PHRASES:
        if alias in k:
            return "Đúng sai", f"keyword '{alias}' → Đúng sai"
    if k2 in _DS_EXACT or k in _DS_EXACT:
        return "Đúng sai", f"alias '{raw}' → Đúng sai"
    if re.search(r"\b(ds|tf)\b", k):
        m = re.search(r"\b(ds|tf)\b", k).group(0)  # type: ignore[union-attr]
        return "Đúng sai", f"abbrev '\\b{m}\\b' → Đúng sai"

    # ── TRẢ LỜI NGẮN ─────────────────────────────────────────────────────────
    _TLN_PHRASES = ["tra loi ngan", "short answer", "shortanswer",
                    "dien vao cho trong", "dien so", "viet so", "dien khuyet"]
    _TLN_EXACT   = {"tln", "short", "shortans", "sa", "fill", "fillin",
                    "dien", "tln4", "tln5"}
    for alias in _TLN_PHRASES:
        if alias in k:
            return "Trả lời ngắn", f"keyword '{alias}' → Trả lời ngắn"
    if k2 in _TLN_EXACT or k in _TLN_EXACT:
        return "Trả lời ngắn", f"alias '{raw}' → Trả lời ngắn"

    # ── TỰ LUẬN ──────────────────────────────────────────────────────────────
    _TL_PHRASES = ["tu luan", "essay", "bai luan", "tu luan dai"]
    _TL_EXACT   = {"tl", "tl1", "tl2"}
    for alias in _TL_PHRASES:
        if alias in k:
            return "Tự luận", f"keyword '{alias}' → Tự luận"
    if k2 in _TL_EXACT or k in _TL_EXACT:
        return "Tự luận", f"alias '{raw}' → Tự luận"

    # ── TRẮC NGHIỆM ──────────────────────────────────────────────────────────
    _TN_PHRASES = ["trac nghiem", "tracnghiem", "multiple choice", "multiplechoice",
                   "4 lua chon", "bon lua chon", "4 phuong an", "bon phuong an",
                   "chon dap an", "chon mot dap an"]
    _TN_EXACT   = {"tn", "tn4", "tn5", "mcq", "mcq4", "mc", "tnkq", "tnbb", "tn1"}
    for alias in _TN_PHRASES:
        if alias in k:
            return "Trắc nghiệm", f"keyword '{alias}' → Trắc nghiệm"
    if k2 in _TN_EXACT or k in _TN_EXACT:
        return "Trắc nghiệm", f"alias '{raw}' → Trắc nghiệm"

    # ── Fallback: chuỗi gốc chứa tên chuẩn (có/không dấu) ───────────────────
    _std_map = {
        "trắc nghiệm": "Trắc nghiệm", "trac nghiem": "Trắc nghiệm",
        "đúng sai":    "Đúng sai",    "dung sai":    "Đúng sai",
        "trả lời ngắn": "Trả lời ngắn", "tra loi ngan": "Trả lời ngắn",
        "tự luận":     "Tự luận",     "tu luan":     "Tự luận",
    }
    for pat, val in _std_map.items():
        if pat in k:
            return val, f"substring '{pat}' → {val}"

    # Không nhận ra — cảnh báo nhưng không crash, về Trắc nghiệm
    return "Trắc nghiệm", f"⚠ không nhận ra '{raw}' → mặc định Trắc nghiệm"


def norm_dang(s: Any) -> str:
    """Chuẩn hóa tên dạng câu về 4 giá trị chuẩn (wrapper của norm_dang_explain).

    Giá trị chuẩn: "Trắc nghiệm" | "Đúng sai" | "Trả lời ngắn" | "Tự luận"
    Dùng norm_dang_explain() khi cần lý do chuyển đổi để log/cảnh báo.
    """
    return norm_dang_explain(s)[0]


def bump_count(d: Dict[str, int], key: str) -> None:
    if not key:
        return
    d[key] = int(d.get(key, 0)) + 1


def question_mucdo_parts(q: Dict[str, Any]) -> List[str]:
    lv = clean(q.get("MucDo", "")).upper()
    parts = [p.strip() for p in re.split(r"[,;/|]+", lv) if p.strip()]
    if parts:
        return parts
    return [lv] if lv else []


def infographic_mucdo_label(q: Dict[str, Any]) -> str:
    """Chuẩn hóa mức độ từ cột I để đưa vào prompt infographic."""
    parts = question_mucdo_parts(q)
    if parts:
        return " · ".join(parts)
    return clean(q.get("MucDo", ""))


def infographic_mucdo_highlight_hint(label: str) -> str:
    """Gợi ý màu badge mức độ trên infographic."""
    if not label:
        return "Sheet chưa ghi mức độ (cột I) — vẫn để badge «Mức độ: ?» hoặc bỏ qua."
    u = key_norm(label)
    hints: List[str] = []
    if "nb" in u or "nen tang" in u:
        hints.append("NB → badge xanh lá, chữ TO")
    if re.search(r"\bth\b", u) or "thong hieu" in u:
        hints.append("TH → badge xanh dương")
    if "vdc" in u:
        hints.append("VDC → badge đỏ đậm")
    elif re.search(r"\bvd\b", u) or "van dung" in u:
        hints.append("VD → badge cam")
    if not hints:
        hints.append(f"Badge nổi bật ghi đúng «{label}»")
    return " | ".join(hints)


