def _learning_request_args() -> Dict[str, str]:
    body = request.get_json(silent=True) or {}
    def val(name: str) -> str:
        return clean(body.get(name) if isinstance(body, dict) and name in body else request.args.get(name, ""))
    return {
        "mon": val("Mon") or val("mon"),
        "lop": val("Lop") or val("lop"),
        "chuong": val("Chuong") or val("chuong"),
        "baihoc": val("BaiHoc") or val("baihoc"),
        "dangbaitap": val("DangBaiTap") or val("dangbaitap"),
    }

def _learning_question_from_body(body: Dict[str, Any]) -> Dict[str, Any]:
    q = body.get("question") if isinstance(body, dict) else {}
    if not isinstance(q, dict):
        q = {}
    out: Dict[str, Any] = {}
    for f in QUESTION_FIELDS:
        out[f] = clean(q.get(f, ""))
    # Nhận thêm query rời nếu client gửi ctx thay vì question đầy đủ.
    for f in ["Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap", "MucDo", "Dang", "CauHoi", "DapAn", "LoiGiai"]:
        if not out.get(f) and isinstance(body, dict):
            out[f] = clean(body.get(f, ""))
    try:
        out["_row"] = int(q.get("_row") or (body.get("row") if isinstance(body, dict) else 0) or 0)
    except Exception:
        out["_row"] = 0
    out["Dang"] = effective_dang(out)
    return out

def _learning_ai_prompt(kind: str, q: Dict[str, Any]) -> str:
    kind = "method" if kind == "method" else "theory"
    opts = "\n".join([f"{L}. {clean(q.get(L,''))}" for L in "ABCD" if clean(q.get(L,''))])
    common = f"""Bạn là giáo viên Toán/Vật lí THPT. Tạo PHƯƠNG PHÁP GIẢI/QUY TRÌNH/CÔNG THỨC LIÊN QUAN ngắn gọn, đúng theo câu hỏi hiện tại để lưu vào Google Sheet.
Yêu cầu chung:
- Trả về DUY NHẤT một JSON object hợp lệ, không markdown, không giải thích ngoài JSON.
- Viết tiếng Việt có dấu.
- Giữ công thức bằng LaTeX inline $...$.
- TUYỆT ĐỐI không nêu đáp án, đáp số, phương án đúng, kết quả cuối của câu đang mở.
- Không thay số, không tính ra đáp án cuối, không giải riêng câu đang mở; chỉ viết kiến thức/quy trình/công thức/lưu ý để tái dùng cho nhiều câu cùng dạng.
- Chỉ chức năng ADMIN «Soát đề GPT» mới được quyền tạo/chốt đáp án.
- Nội dung đủ để học sinh xem lại nhanh, không quá dài.

THÔNG TIN CÂU HỎI:
Môn: {clean(q.get('Mon'))}
Lớp: {clean(q.get('Lop'))}
Chương: {clean(q.get('Chuong'))}
Bài học: {clean(q.get('BaiHoc'))}
Dạng bài tập: {clean(q.get('DangBaiTap'))}
Mức độ: {clean(q.get('MucDo'))}
Dạng câu: {clean(q.get('Dang'))}
Câu hỏi: {clean(q.get('CauHoi'))}
Phương án:
{opts}
(Đáp án Sheet và lời giải Sheet được ẩn trong chức năng tạo học liệu; chỉ Soát đề GPT mới được dùng đáp án.)
"""
    if kind == "theory":
        return common + """
Tạo JSON đúng schema sau:
{
  "TieuDe": "tên kiến thức chính",
  "NoiDungTomTat": "2-4 câu tóm tắt lý thuyết",
  "KienThucTrongTam": "các ý học sinh cần nhớ",
  "CongThuc": "công thức liên quan, có LaTeX nếu cần",
  "DonVi": "đơn vị/ký hiệu nếu có, nếu Toán thì ghi điều kiện/ký hiệu",
  "LuuY": "lưu ý quan trọng",
  "SaiLamThuongGap": "những lỗi học sinh hay mắc",
  "ViDuMau": "một ví dụ mẫu rất ngắn cùng dạng"
}
"""
    return common + """
Nếu Dạng bài tập đang trống/chưa/chưa gán thì phải tự phân loại thành một tên dạng cụ thể trước.
Tạo JSON đúng schema sau:
{
  "DangBaiTap": "tên dạng bài tập cụ thể, không ghi Trắc nghiệm/Đúng sai",
  "TenPhuongPhap": "tên phương pháp giải",
  "DauHieuNhanBiet": "dấu hiệu nhận ra dạng bài",
  "CacBuocGiai": "mỗi bước một dòng, dùng ký tự \n giữa các bước, ví dụ: Bước 1: ...\nBước 2: ...\nBước 3: ...",
  "CongThucSuDung": "công thức/công cụ dùng",
  "MeoNhanh": "mẹo nhanh khi làm trắc nghiệm hoặc kiểm tra kết quả",
  "LoiSaiThuongGap": "lỗi sai thường gặp",
  "ViDuMau": "ví dụ mẫu ngắn cùng dạng, không thay số và không có đáp án cuối",
  "NoiDungLaTeX": "khung dùng chung gồm đúng các môi trường \\begin{dn}...\\end{dn}, \\begin{note}...\\end{note}, \\begin{vidu}...\\end{vidu}; không đưa đáp án cuối"
}
"""

def _learning_ai_call(
    prompt: str,
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Tuple[str, str, str]:
    sys_prompt = "Bạn tạo học liệu ngắn gọn cho giáo viên. Chỉ trả JSON hợp lệ. Không đưa đáp án/đáp số; chỉ Soát đề AI mới được chốt đáp án."
    txt, prov, model, _ki = admin_ai_call_text(
        sys_prompt,
        prompt,
        max_tokens=1600,
        temp=0.25,
        timeout=45,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
    )
    return txt, prov, model

def normalize_method_latex_source(v: Any) -> str:
    """Chuẩn hóa nguồn LaTeX của khung Dạng bài tập.

    Môi trường chính thức:
      \\begin{dn}...\\end{dn}
      \\begin{note}...\\end{note}
      \\begin{vidu}...\\end{vidu}

    Đồng thời sửa các cách gõ cũ: node -> note, vd -> vidu.
    """
    t = clean(v)
    if not t:
        return ""
    if len(t) > 180_000:
        raise ValueError("Khung lý thuyết quá dài (tối đa 180.000 ký tự).")
    replacements = [
        (r"\\begin\s*\{\s*node\s*\}", r"\\begin{note}"),
        (r"\\end\s*\{\s*node\s*\}", r"\\end{note}"),
        (r"\\begin\s*\{\s*kttrongtam\s*\}", r"\\begin{dn}"),
        (r"\\end\s*\{\s*kttrongtam\s*\}", r"\\end{dn}"),
        (r"\\begin\s*\{\s*vd\s*\}", r"\\begin{vidu}"),
        (r"\\end\s*\{\s*vd\s*\}", r"\\end{vidu}"),
        (r"\\begin\s*\{\s*dinhnghia\s*\}", r"\\begin{dn}"),
        (r"\\end\s*\{\s*dinhnghia\s*\}", r"\\end{dn}"),
    ]
    for pattern, repl in replacements:
        t = re.sub(pattern, repl, t, flags=re.I)
    t = re.sub(r"%\[[^\]]*\]", "", t)
    t = re.sub(r"\\hfill\b", "", t)
    t = _latex_fold_loigiai_in_content(t)
    t = _latex_convert_robot_text_cmds(t)
    t = re.sub(r"[ \t]+\n", "\n", t)
    t = re.sub(r"\n{4,}", "\n\n\n", t)
    return t.strip()


def _format_method_steps_text(v: Any) -> str:
    """Đưa Bước 1/Bước 2... về mỗi bước một dòng để app hiển thị dễ đọc."""
    t = normalize_latex_light(v)
    if not t:
        return ""
    # Nếu AI trả trên một dòng: Bước 1: ... Bước 2: ... → xuống dòng trước Bước 2...
    t = re.sub(r"\s*(Bước\s*\d+\s*[:.])", lambda m: (m.group(1) if m.start() == 0 else "\n" + m.group(1)), t, flags=re.I)
    t = re.sub(r"\s*(B\d+\s*[:.])", lambda m: (m.group(1) if m.start() == 0 else "\n" + m.group(1)), t, flags=re.I)
    t = re.sub(r"\n{3,}", "\n\n", t)
    return t.strip()

def _coerce_learning_item(kind: str, q: Dict[str, Any], obj: Dict[str, Any]) -> Dict[str, Any]:
    kind = "method" if kind == "method" else "theory"
    now = datetime.now().strftime("%d/%m/%Y %H:%M")
    if kind == "theory":
        item = {f: "" for f in LEARNING_THEORY_FIELDS}
        item.update({
            "Mon": clean(q.get("Mon")),
            "Lop": clean(q.get("Lop")),
            "Chuong": clean(q.get("Chuong")),
            "BaiHoc": clean(q.get("BaiHoc")),
            "TieuDe": clean(obj.get("TieuDe") or q.get("BaiHoc") or q.get("DangBaiTap") or "Lý thuyết"),
            "LyThuyet": normalize_latex_light(obj.get("LyThuyet", "")),
            "NoiDungTomTat": normalize_latex_light(obj.get("NoiDungTomTat", "")),
            "KienThucTrongTam": normalize_latex_light(obj.get("KienThucTrongTam", "")),
            "CongThuc": normalize_latex_light(obj.get("CongThuc", "")),
            "DonVi": normalize_latex_light(obj.get("DonVi", "")),
            "LuuY": normalize_latex_light(obj.get("LuuY", "")),
            "SaiLamThuongGap": normalize_latex_light(obj.get("SaiLamThuongGap", "")),
            "ViDuMau": normalize_latex_light(obj.get("ViDuMau", "")),
            "NoiDungLaTeX": normalize_method_latex_source(obj.get("NoiDungLaTeX", "")),
            "TrangThai": "OK",
            "NgayCapNhat": now,
        })
        item["ID"] = "LT_" + stable_hash("|".join(item.get(k,"") for k in ["Mon","Lop","Chuong","BaiHoc"]), 12)
        return item
    item = {f: "" for f in LEARNING_METHOD_FIELDS}
    item.update({
        "Mon": clean(q.get("Mon")),
        "Lop": clean(q.get("Lop")),
        "Chuong": clean(q.get("Chuong")),
        "BaiHoc": clean(q.get("BaiHoc")),
        "DangBaiTap": (clean(q.get("DangBaiTap")) if not _is_bad_dangbaitap_value(q.get("DangBaiTap")) else "") or clean(obj.get("DangBaiTap")) or clean(obj.get("TenPhuongPhap")) or "Phương pháp giải",
        "TenPhuongPhap": clean(obj.get("TenPhuongPhap") or obj.get("DangBaiTap") or q.get("DangBaiTap") or "Phương pháp giải"),
        "DauHieuNhanBiet": normalize_latex_light(obj.get("DauHieuNhanBiet", "")),
        "CacBuocGiai": _format_method_steps_text(obj.get("CacBuocGiai", "")),
        "CongThucSuDung": normalize_latex_light(obj.get("CongThucSuDung", "")),
        "MeoNhanh": normalize_latex_light(obj.get("MeoNhanh", "")),
        "LoiSaiThuongGap": normalize_latex_light(obj.get("LoiSaiThuongGap", "")),
        "ViDuMau": normalize_latex_light(obj.get("ViDuMau", "")),
        "NoiDungLaTeX": normalize_method_latex_source(obj.get("NoiDungLaTeX", "")),
        "TrangThai": "OK",
        "NgayCapNhat": now,
    })
    item["ID"] = "PP_" + stable_hash("|".join(item.get(k,"") for k in ["Mon","Lop","Chuong","BaiHoc","DangBaiTap"]), 12)
    return item


def _is_bad_dangbaitap_value(v: Any) -> bool:
    t = key_norm(v)
    if not t:
        return True
    if t in {"chua", "chua gan", "chua phan loai", "chua co", "none", "null", "khong ro", "khac"}:
        return True
    if t in {"trac nghiem", "dung sai", "tra loi ngan", "tu luan", "tn", "ds", "tln", "tl"}:
        return True
    return False


def load_dbt_orders() -> Dict[str, List[str]]:
    """ADMIN: thứ tự hiển thị Dạng BT theo MaDe — ưu tiên sheet DBT_ThuTu, fallback file JSON."""
    merged: Dict[str, List[str]] = {}
    try:
        if os.path.isfile(DBT_ORDER_FILE):
            with open(DBT_ORDER_FILE, encoding="utf-8") as f:
                obj = json.load(f)
            raw = obj.get("orders") if isinstance(obj, dict) else obj
            if isinstance(raw, dict):
                for k, v in raw.items():
                    if not isinstance(v, list):
                        continue
                    names = [clean(x) for x in v if clean(x) and not _is_bad_dangbaitap_value(x)]
                    if names:
                        merged[clean(k)] = names
    except Exception:
        pass
    try:
        st = get_store()
        if st.sheet is not None:
            sheet_orders = st.read_dbt_orders_from_sheet()
            if sheet_orders:
                merged.update(sheet_orders)
    except Exception:
        pass
    return merged


def save_dbt_orders(orders: Dict[str, List[str]]) -> None:
    os.makedirs(os.path.dirname(DBT_ORDER_FILE), exist_ok=True)
    tmp = DBT_ORDER_FILE + ".tmp"
    payload = {"orders": orders, "updated_at": datetime.now().strftime("%d/%m/%Y %H:%M")}
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    os.replace(tmp, DBT_ORDER_FILE)


def _normalize_pdf_link_item(raw: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(raw, dict):
        return None
    name = clean(raw.get("name", ""))
    url = clean(raw.get("url", ""))
    if not name or not url:
        return None
    try:
        pid = int(raw.get("id") or 0)
    except Exception:
        pid = 0
    if not pid:
        pid = int(time.time() * 1000)
    quyen = clean(raw.get("quyen", "FREE")) or "FREE"
    return {
        "id": pid,
        "name": name,
        "url": url,
        "quyen": quyen,
        "at": clean(raw.get("at", "")),
    }


def load_pdf_links() -> Dict[str, Any]:
    default: Dict[str, Any] = {"math": [], "phys": [], "updated_at": ""}
    try:
        if os.path.isfile(PDF_LINKS_FILE):
            with open(PDF_LINKS_FILE, encoding="utf-8") as f:
                obj = json.load(f)
            if isinstance(obj, dict):
                out = dict(default)
                for sub in ("math", "phys"):
                    raw = obj.get(sub) or []
                    if isinstance(raw, list):
                        items = []
                        for row in raw:
                            norm = _normalize_pdf_link_item(row)
                            if norm:
                                items.append(norm)
                        out[sub] = items
                out["updated_at"] = clean(obj.get("updated_at", ""))
                return out
    except Exception:
        pass
    return default


def save_pdf_links(links: Dict[str, Any]) -> None:
    payload = {
        "math": [],
        "phys": [],
        "updated_at": datetime.now().strftime("%d/%m/%Y %H:%M"),
    }
    for sub in ("math", "phys"):
        raw = (links or {}).get(sub) or []
        if isinstance(raw, list):
            for row in raw:
                norm = _normalize_pdf_link_item(row)
                if norm:
                    payload[sub].append(norm)
    os.makedirs(os.path.dirname(PDF_LINKS_FILE), exist_ok=True)
    tmp = PDF_LINKS_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    os.replace(tmp, PDF_LINKS_FILE)


def pdf_links_public() -> Dict[str, Any]:
    data = load_pdf_links()
    return {
        "math": list(data.get("math") or []),
        "phys": list(data.get("phys") or []),
        "updated_at": clean(data.get("updated_at", "")),
    }


def save_dbt_order_one(made: str, names: List[str], orders: Optional[Dict[str, List[str]]] = None) -> Dict[str, List[str]]:
    """Lưu thứ tự một MaDe — file JSON + sheet DBT_ThuTu + cập nhật catalog RAM."""
    made = clean(made)
    names = [clean(x) for x in (names or []) if clean(x) and not _is_bad_dangbaitap_value(x)]
    orders = dict(orders if orders is not None else load_dbt_orders())
    if names:
        orders[made] = names
    elif made in orders:
        del orders[made]
    save_dbt_orders(orders)
    try:
        st = get_store()
        if made and names:
            st.upsert_dbt_order_on_sheet(made, names)
        if st.catalog:
            st.apply_dbt_orders_to_catalog(orders)
    except Exception:
        pass
    return orders


def ordered_dbt_names(
    made: str,
    counts: Dict[str, int],
    orders: Optional[Dict[str, List[str]]] = None,
) -> List[str]:
    """Sắp xếp tên dạng BT: ưu tiên thứ tự ADMIN, phần còn lại theo số câu giảm dần."""
    orders = orders if orders is not None else load_dbt_orders()
    custom = orders.get(clean(made)) or []
    canon: Dict[str, str] = {}
    for k in (counts or {}):
        if k == DBT_FILTER_UNCLASSIFIED or _is_bad_dangbaitap_value(k):
            continue
        canon[key_norm(k)] = clean(k)
    out: List[str] = []
    seen: set = set()
    for name in custom:
        kn = key_norm(name)
        if kn in canon and kn not in seen:
            out.append(canon[kn])
            seen.add(kn)
    rest = sorted(
        [canon[kn] for kn in canon if kn not in seen],
        key=lambda nm: (-(counts.get(nm, 0) or 0), key_norm(nm)),
    )
    out.extend(rest)
    return out


def patch_dbt_order_after_merge(made: str, old_names: List[str], new_name: str) -> None:
    made = clean(made)
    new_name = clean(new_name)
    if not made or not new_name:
        return
    orders = load_dbt_orders()
    lst = list(orders.get(made) or [])
    if not lst:
        return
    old_keys = {key_norm(clean(x)) for x in old_names if clean(x)}
    new_lst: List[str] = []
    replaced = False
    for name in lst:
        if key_norm(name) in old_keys:
            if not replaced:
                new_lst.append(new_name)
                replaced = True
        else:
            new_lst.append(name)
    if replaced:
        save_dbt_order_one(made, new_lst, orders)


def _catalog_item_dbt_values(item: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    fc = (item.get("FilterCounts") or {}).get("dangbaitap") or {}
    if isinstance(fc, dict):
        for k in fc:
            v = clean(k)
            if v and not _is_bad_dangbaitap_value(v):
                out.append(v)
    raw = clean(item.get("DangBaiTap", ""))
    if raw:
        for part in re.split(r"[,;|]+", raw):
            v = clean(part)
            if v and not _is_bad_dangbaitap_value(v):
                out.append(v)
    return out


def _lesson_scope_key(q: Dict[str, Any]) -> str:
    return "|".join([
        key_norm(clean(q.get("Mon", ""))),
        key_norm(clean(q.get("Chuong", ""))),
        key_norm(clean(q.get("BaiHoc", ""))),
    ])


def _dbt_similarity_py(a: str, b: str) -> float:
    a, b = key_norm(a), key_norm(b)
    if not a or not b:
        return 0.0
    if a == b or a in b or b in a:
        return 0.9
    ta, tb = set(a.split()), set(b.split())
    if not ta or not tb:
        return 0.0
    ov = len(ta & tb)
    return ov / min(len(ta), len(tb))


def _nearest_dbt_canonical(name: str, canonicals: List[str]) -> str:
    if not canonicals:
        return name
    best = canonicals[0]
    best_sc = -1.0
    for c in canonicals:
        sc = _dbt_similarity_py(name, c)
        if sc > best_sc:
            best_sc = sc
            best = c
    return best if best_sc >= 0.35 else canonicals[0]


def _consolidate_dangbaitap_per_lesson(
    questions: List[Dict[str, Any]], max_types: int = DBT_MAX_TYPES_PER_LESSON
) -> Dict[str, Any]:
    """Gom tối đa max_types dạng BT/khối bài học — gán lại _AiDangBaiTap cho câu bị loãng."""
    merged_total = 0
    lesson_stats: Dict[str, Any] = {}
    by_lesson: Dict[str, List[Dict[str, Any]]] = {}
    for q in questions:
        by_lesson.setdefault(_lesson_scope_key(q), []).append(q)

    for sk, group in by_lesson.items():
        buckets: Dict[str, Tuple[str, int]] = {}
        for q in group:
            v = clean(q.get("_AiDangBaiTap") or "")
            if not v or _is_bad_dangbaitap_value(v):
                continue
            kn = key_norm(v)
            if kn not in buckets:
                buckets[kn] = (v, 0)
            buckets[kn] = (buckets[kn][0], buckets[kn][1] + 1)

        if len(buckets) <= max_types:
            lesson_stats[sk] = {
                "types": len(buckets),
                "merged": 0,
                "canonical": [buckets[k][0] for k in buckets],
            }
            continue

        remap: Dict[str, str] = {kn: buckets[kn][0] for kn in buckets}

        def dist_names() -> List[str]:
            seen: set = set()
            out: List[str] = []
            for kn in remap:
                dn = key_norm(remap[kn])
                if dn not in seen:
                    seen.add(dn)
                    out.append(remap[kn])
            return out

        while len(dist_names()) > max_types:
            agg: Dict[str, int] = {}
            for kn in remap:
                dn = key_norm(remap[kn])
                agg[dn] = agg.get(dn, 0) + 1
            ranked = sorted(agg.items(), key=lambda x: (x[1], len(x[0])))
            victim_n = ranked[0][0]
            victim_display = next(remap[kn] for kn in remap if key_norm(remap[kn]) == victim_n)
            others_unique: List[str] = []
            seen_o: set = set()
            for kn in remap:
                if key_norm(remap[kn]) == victim_n:
                    continue
                ko = key_norm(remap[kn])
                if ko not in seen_o:
                    seen_o.add(ko)
                    others_unique.append(remap[kn])
            target = _nearest_dbt_canonical(victim_display, others_unique)
            for kn in list(remap.keys()):
                if key_norm(remap[kn]) == victim_n:
                    remap[kn] = target

        canonical = dist_names()[:max_types]
        n_merge = 0
        for q in group:
            v = clean(q.get("_AiDangBaiTap") or "")
            kn = key_norm(v)
            if kn not in remap:
                continue
            new_v = remap[kn]
            if key_norm(new_v) != kn:
                q["_AiDangBaiTap"] = new_v
                q["_AiReason"] = (
                    clean(q.get("_AiReason", ""))
                    + f" (gộp về «{new_v}» — tối đa {max_types} dạng/bài)"
                ).strip()[:180]
                q["_AiMatchedExisting"] = True
                n_merge += 1
                merged_total += 1

        lesson_stats[sk] = {"types": len(canonical), "merged": n_merge, "canonical": canonical}

    return {"merged": merged_total, "lessons": lesson_stats}


def _lesson_dbt_canonical_from_questions(
    questions: List[Dict[str, Any]], max_types: int = DBT_MAX_TYPES_PER_LESSON
) -> Dict[str, List[str]]:
    by_lesson: Dict[str, Dict[str, Tuple[str, int]]] = {}
    for q in questions:
        sk = _lesson_scope_key(q)
        v = clean(q.get("_AiDangBaiTap") or q.get("DangBaiTap") or "")
        if not v or _is_bad_dangbaitap_value(v):
            continue
        kn = key_norm(v)
        bucket = by_lesson.setdefault(sk, {})
        if kn not in bucket:
            bucket[kn] = (v, 0)
        bucket[kn] = (bucket[kn][0], bucket[kn][1] + 1)
    out: Dict[str, List[str]] = {}
    for sk, bucket in by_lesson.items():
        ordered = sorted(bucket.keys(), key=lambda k: (-bucket[k][1], bucket[k][0].lower()))
        out[sk] = [bucket[k][0] for k in ordered[:max_types]]
    return out


def _scoped_dangbaitap_suggestions(store: "SheetStore", q: Dict[str, Any], limit: int = 50) -> Tuple[List[str], str]:
    mon = clean(q.get("Mon", ""))
    chuong = clean(q.get("Chuong", ""))
    bai = clean(q.get("BaiHoc", ""))

    def matches(item: Dict[str, Any], level: str) -> bool:
        if mon and key_norm(item.get("Mon", "")) != key_norm(mon):
            return False
        if level == "mon":
            return True
        if chuong and key_norm(item.get("Chuong", "")) != key_norm(chuong):
            return False
        if level == "chuong":
            return True
        if bai and key_norm(item.get("BaiHoc", "")) != key_norm(bai):
            return False
        return True

    counts: Dict[str, int] = {}
    canon: Dict[str, str] = {}
    level = "none"

    def bump(vals: List[str], weight: int = 1) -> None:
        for v in vals:
            k = key_norm(v)
            counts[k] = counts.get(k, 0) + max(weight, 0) or 1
            if k not in canon:
                canon[k] = v

    for item in store.catalog:
        if matches(item, "bai"):
            bump(_catalog_item_dbt_values(item))
    if counts:
        level = "bai"
    elif chuong:
        for item in store.catalog:
            if matches(item, "chuong"):
                bump(_catalog_item_dbt_values(item))
        if counts:
            level = "chuong"
    if not counts and mon:
        for item in store.catalog:
            if matches(item, "mon"):
                bump(_catalog_item_dbt_values(item))
        if counts:
            level = "mon"

    for qq in store.questions:
        dbt = clean(qq.get("DangBaiTap", ""))
        if not dbt or _is_bad_dangbaitap_value(dbt):
            continue
        if matches(qq, "bai"):
            bump([dbt])
        elif chuong and matches(qq, "chuong"):
            bump([dbt])
        elif mon and matches(qq, "mon"):
            bump([dbt])

    cur = clean(q.get("DangBaiTap", ""))
    if cur and not _is_bad_dangbaitap_value(cur):
        bump([cur], 0)

    ordered = sorted(canon.keys(), key=lambda k: (-counts.get(k, 0), canon[k].lower()))
    return [canon[k] for k in ordered[:limit]], level


def _merge_dangbaitap_suggestions(*lists: Iterable[str], limit: int = 50) -> List[str]:
    seen: set = set()
    out: List[str] = []
    for lst in lists:
        for x in lst or []:
            v = clean(x)
            if not v or _is_bad_dangbaitap_value(v):
                continue
            k = key_norm(v)
            if k in seen:
                continue
            seen.add(k)
            out.append(v)
            if len(out) >= limit:
                return out
    return out


def _resolve_dangbaitap_to_suggestions(raw: str, suggestions: List[str]) -> Tuple[str, Optional[str], bool]:
    """Chuẩn hóa tên AI về dạng đã có trong ngân hàng (tránh trùng gần giống)."""
    raw = clean(raw)
    if not raw or not suggestions:
        return raw, None, False
    rn = key_norm(raw)
    for s in suggestions:
        if key_norm(s) == rn:
            return s, s, True
    best: Optional[str] = None
    best_score = -1
    for s in suggestions:
        sn = key_norm(s)
        if rn in sn or sn in rn:
            score = min(len(rn), len(sn))
            if score > best_score:
                best_score = score
                best = s
    if best:
        return best, best, True
    raw_tokens = set(rn.split())
    if len(raw_tokens) >= 2:
        for s in suggestions:
            st = set(key_norm(s).split())
            overlap = len(raw_tokens & st)
            if overlap >= 2 and overlap >= max(2, int(len(raw_tokens) * 0.55)):
                return s, s, True
    return raw, None, False


def _detect_dangbaitap_prompt(q: Dict[str, Any], dangbaitap_suggestions: Optional[List[str]] = None, scope_level: str = "") -> str:
    sug_limit = DBT_MAX_TYPES_PER_LESSON if scope_level == "bai" else 50
    sug = [clean(x) for x in (dangbaitap_suggestions or []) if clean(x)]
    sug = [x for x in sug if not _is_bad_dangbaitap_value(x)][:sug_limit]
    scope_note = ""
    if scope_level == "bai":
        scope_note = " (ưu tiên cao nhất — cùng Môn + Chương + Bài học)"
    elif scope_level == "chuong":
        scope_note = " (cùng Môn + Chương)"
    elif scope_level == "mon":
        scope_note = " (cùng Môn)"
    if sug:
        sug_block = (
            f"\n\n★ DANH SÁCH DẠNG BÀI TẬP ĐÃ CÓ TRONG NGÂN HÀNG{scope_note} — BẮT BUỘC ƯU TIÊN:\n"
            + "\n".join(f"{i+1}. {x}" for i, x in enumerate(sug))
            + "\n\nQuy tắc đồng bộ tên:\n"
            "- Nếu câu thuộc một dạng trong danh sách trên → trả về ĐÚNG NGUYÊN VĂN tên đó (copy y hệt, không đổi dấu/hoa thường).\n"
            "- Chỉ đặt tên mới khi KHÔNG có dạng nào trong danh sách phù hợp.\n"
            "- Không tạo biến thể gần giống (vd đã có «Xác định li độ» thì không trả «Xác định li độ dao động»).\n"
        )
    else:
        sug_block = "\n\n(Chưa có dạng nào trong phạm vi Môn/Chương/Bài — có thể đặt tên mới ngắn gọn, 4-12 từ.)\n"
    opts = "\n".join([f"{L}. {clean(q.get(L,''))}" for L in "ABCD" if clean(q.get(L,''))])
    cap_note = ""
    if scope_level == "bai":
        cap_note = f"\n- Trong cùng Bài học: tối đa {DBT_MAX_TYPES_PER_LESSON} dạng khác nhau — ưu tiên gom câu cùng phương pháp, tái dùng tên có sẵn.\n"
    return f"""Bạn là giáo viên THPT đang phân loại ngân hàng câu hỏi.
Nhiệm vụ: đặt tên DẠNG BÀI TẬP ngắn gọn, cụ thể, để lưu vào cột DangBaiTap và dùng làm khóa gọi Phương pháp giải.

Yêu cầu:
- Trả về DUY NHẤT một JSON object hợp lệ, không markdown.
- Không trả 'Trắc nghiệm', 'Đúng sai', 'Trả lời ngắn', 'Tự luận' vì đó là DẠNG CÂU, không phải dạng bài tập.
- Tên dạng nên 4-12 từ, đủ cụ thể, dùng được cho nhiều câu cùng phương pháp.{cap_note}
- Ưu tiên tên như: Tiệm cận ngang hàm phân thức; Đọc số nghiệm từ đồ thị; Xác định li độ, vận tốc, gia tốc...
- Không nêu đáp án/đáp số/kết quả cuối; chỉ Soát đề GPT mới được chốt đáp án.{sug_block}

THÔNG TIN CÂU:
Môn: {clean(q.get('Mon'))}
Lớp: {clean(q.get('Lop'))}
Chương: {clean(q.get('Chuong'))}
Bài học: {clean(q.get('BaiHoc'))}
Dạng câu: {clean(q.get('Dang'))}
Mức độ: {clean(q.get('MucDo'))}
Dạng bài tập hiện tại: {clean(q.get('DangBaiTap'))}
Câu hỏi: {clean(q.get('CauHoi'))}
Phương án:
{opts}
(Đáp án/lời giải bị ẩn; chỉ phân loại dạng bài tập, không chốt đáp số.)

Schema:
{{
  "DangBaiTap": "tên dạng — copy nguyên văn từ danh sách nếu khớp",
  "reason": "lý do rất ngắn",
  "used_existing": true hoặc false
}}
"""


@app.route("/api/ai/detect-dangbaitap-update", methods=["POST"])
def api_ai_detect_dangbaitap_update():
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được gán Dạng bài tập."}), 403
    body = request.get_json(silent=True) or {}
    q = _learning_question_from_body(body)
    client_sug = body.get("dangbaitap_suggestions") or []
    if not isinstance(client_sug, list):
        client_sug = []
    st = get_store()
    st.ensure_questions_loaded()
    scoped_sug, scope_level = _scoped_dangbaitap_suggestions(st, q, limit=50)
    meta_sug: List[str] = []
    try:
        meta_sug = ((st.meta() or {}).get("filters") or {}).get("DangBaiTap") or []
    except Exception:
        meta_sug = []
    suggestions = _merge_dangbaitap_suggestions(scoped_sug, client_sug, meta_sug, limit=50)
    save_sheet = body.get("save", True)
    if save_sheet is False or str(save_sheet).lower() in ("0", "false", "no"):
        save_sheet = False
    else:
        save_sheet = True
    prompt = _detect_dangbaitap_prompt(q, suggestions, scope_level=scope_level)
    try:
        force, allow = admin_ai_body_params(body)
        raw, provider, model = _learning_ai_call(
            prompt, force_provider=force, allow_gpt_fallback=allow
        )
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)
    obj = _extract_ai_json_object(raw)
    ai_raw = clean((obj or {}).get("DangBaiTap") or (obj or {}).get("dangbaitap") or "")
    if not ai_raw or _is_bad_dangbaitap_value(ai_raw):
        return jsonify({"error": "GPT chưa trả Dạng bài tập hợp lệ.", "raw": raw[:2000]}), 500
    val, synced_from, matched_existing = _resolve_dangbaitap_to_suggestions(ai_raw, suggestions)
    row = int(body.get("row") or q.get("_row") or 0)
    qid = clean(body.get("id") or body.get("ID") or q.get("ID") or "")
    res = {
        "ok": True,
        "DangBaiTap": val,
        "ai_raw": ai_raw,
        "synced_from": synced_from or "",
        "matched_existing": bool(matched_existing),
        "scope_level": scope_level,
        "suggestion_count": len(suggestions),
        "reason": clean((obj or {}).get("reason", "")),
        "provider_used": provider,
        "model": model,
        "saved": False,
    }
    if save_sheet and row >= 2:
        upd = st.update_question(row, {"DangBaiTap": val}, qid)
        res.update({"row": upd.get("row", row), "fields": upd.get("fields", [])})
        res["saved"] = True
    elif not save_sheet:
        sync_note = f" (đồng bộ từ «{synced_from}»)" if synced_from and synced_from != ai_raw else ""
        res.update({"message": f"GPT gợi ý Dạng bài tập{sync_note}, chưa lưu Sheet."})
    else:
        res.update({"warning": "Chưa có dòng Sheet nên chỉ trả gợi ý, chưa lưu."})
    return jsonify(res)

