def _ai_gemini_client_ready() -> bool:
    return callable(solve_problem_with_gemini)


def _ai_gemini_resolve_question(data: Dict[str, Any]) -> Tuple[Dict[str, Any], int, str]:
    """Lấy câu hỏi từ sid/index hoặc problem_text/question trong body."""
    sid = clean(data.get("sid"))
    try:
        idx = int(data.get("index", 0))
    except Exception:
        idx = 0
    if sid:
        restore = quiz_restore_payload_from_body(data)
        ses = get_store().check_quiz_session(sid, restore)
        qs = ses["questions"]
        if not (0 <= idx < len(qs)):
            raise RuntimeError("Số câu không hợp lệ")
        store = get_store()
        q = assistant_question_from_session(store, ses, qs, idx)
        block = build_ai_question_block(
            q,
            data.get("answer", ""),
            include_sheet_answer=is_admin(),
            include_loigiai=is_admin(),
        )
        return q, idx, block
    q_in = data.get("question") or data.get("q") or {}
    if isinstance(q_in, dict) and clean(q_in.get("CauHoi")):
        q = {f: clean(q_in.get(f, "")) for f in QUESTION_FIELDS}
        q["Dang"] = effective_dang(q)
        block = build_ai_question_block(
            q,
            data.get("answer", ""),
            include_sheet_answer=is_admin(),
            include_loigiai=is_admin(),
        )
        return q, -1, block
    pt = clean(data.get("problem_text", data.get("text", "")))
    if pt:
        ctx = data.get("context") if isinstance(data.get("context"), dict) else {}
        q = {f: clean(ctx.get(f, "")) for f in QUESTION_FIELDS}
        q["CauHoi"] = pt
        q["Dang"] = effective_dang(q) if clean(q.get("Dang")) else clean(ctx.get("Dang", "Trắc nghiệm"))
        return q, -1, pt
    raise RuntimeError("Thiếu sid/index hoặc problem_text/question.")


def _ai_gemini_image_payload(q: Dict[str, Any]) -> Optional[Dict[str, str]]:
    vision = prepare_question_vision(q)
    if not vision.get("vision_ready"):
        return None
    b64 = clean(vision.get("image_b64", ""))
    mime = clean(vision.get("image_mime", ""))
    if not b64 or not mime:
        return None
    return {"b64": b64, "mime": mime}


def _ai_gemini_solve_handler():
    if not _ai_gemini_client_ready():
        return jsonify({"error": "Module ai_gemini_client chưa sẵn sàng."}), 500
    bad = require_login_json()
    if bad:
        return bad
    bad_ai = require_ai_hint_json()
    if bad_ai:
        return bad_ai
    refresh_session_role_from_store()
    data = request.get_json(silent=True) or {}
    try:
        q, idx, problem_text = _ai_gemini_resolve_question(data)
    except Exception as e:
        return jsonify({"error": str(e)}), 400
    hard = bool(data.get("hard"))
    keys = load_ai_keys("GEMINI")
    if not keys:
        return jsonify({"error": "Chưa có Gemini API key."}), 400
    image = _ai_gemini_image_payload(q)
    if isinstance(data.get("image"), dict):
        img_in = data["image"]
        b64 = clean(img_in.get("b64", img_in.get("data", "")))
        mime = clean(img_in.get("mime", img_in.get("mime_type", "image/png")))
        if b64 and mime:
            image = {"b64": b64, "mime": mime}

    @copy_current_request_context
    def _worker():
        return solve_problem_with_gemini(
            problem_text,
            image=image,
            hard=hard,
            api_keys=keys,
            context=q,
            admin_mode=is_admin(),
            user_answer=clean(data.get("answer", "")),
        )

    try:
        with ThreadPoolExecutor(max_workers=1) as pool:
            result = pool.submit(_worker).result(timeout=ASSISTANT_HTTP_MAX_SEC)
    except FuturesTimeout:
        return jsonify({"ok": False, "error": f"Quá {ASSISTANT_HTTP_MAX_SEC}s — thử lại hoặc bật hard=false."}), 504
    if not result.get("ok"):
        return jsonify(result), 400
    model_used = clean(result.get("model", ""))
    tier = "pro" if hard else "flash"
    return jsonify({
        **result,
        "index": idx,
        "show_answer": is_admin(),
        "hard": hard,
        "version": APP_VERSION,
        "message": f"Giải bài — {model_used or ('gemini-2.5-' + tier)}.",
    })


