@app.route("/api/admin/normalize-latex", methods=["POST"])
def api_admin_normalize_latex():
    """ADMIN: chuẩn hóa LaTeX tức thì (không AI) — từng bước hoặc đầy đủ."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được chuẩn hóa LaTeX."}), 403
    body = request.get_json(silent=True) or {}
    field = clean(body.get("field", ""))
    context = body.get("context") or {}
    text = clean(body.get("text", ""))
    action = clean(body.get("action", "full")) or "full"
    selection = body.get("selection")
    if not text and not (selection and clean(selection.get("full"))):
        return jsonify({"ok": True, "text": "", "changed": False, "action": action})
    if selection and clean(selection.get("full")):
        full = clean(selection.get("full"))
        fixed = apply_latex_normalize_with_selection(full, action, selection)
    else:
        fixed = apply_latex_normalize_with_selection(text, action, None)
    if action == "loigiai_abcd":
        base = normalize_latex_light(fixed)
        fixed = normalize_loigiai_abcd(base, context)
    elif field == "LoiGiai":
        dang = effective_dang(context)
        if dang == "Đúng sai":
            fixed = normalize_ds_loigiai(
                fixed,
                context,
                use_sheet_dapan=looks_like_dungsai_answer(context.get("DapAn", "")),
            )
        elif dang == "Trắc nghiệm" and action == "full" and _loigiai_has_splittable_chunks(fixed):
            fixed = normalize_tn_loigiai_abcd(fixed, context)
    still_broken = not _latex_structure_ok(fixed)
    orig_cmp = clean(selection.get("full") if selection else text)
    action_label = next(
        (x["label"] for x in LATEX_NORMALIZE_CATALOG if x["id"] == action),
        action,
    )
    seg_only = False
    if selection:
        try:
            seg_only = int(selection.get("end", 0)) > int(selection.get("start", 0))
        except (TypeError, ValueError):
            seg_only = False
    return jsonify({
        "ok": True,
        "text": fixed,
        "changed": fixed != orig_cmp,
        "still_broken": still_broken,
        "action": action,
        "action_label": action_label,
        "segment_only": seg_only,
    })




@app.route("/api/admin/claude-fix-latex", methods=["POST"])
def api_admin_claude_fix_latex():
    """ADMIN: gọi Anthropic Claude qua server để sửa LaTeX (tránh CORS)."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN."}), 403
    body = request.get_json(silent=True) or {}
    text = clean(body.get("text", ""))
    if not text:
        return jsonify({"ok": True, "text": "", "changed": False})
    # Lấy key: ưu tiên key trong request (từ localStorage client), fallback server key
    client_key = clean(body.get("anthropic_key", ""))
    server_keys = load_ai_keys("ANTHROPIC") if not client_key else []
    api_key = client_key or (server_keys[0] if server_keys else "")
    if not api_key:
        return jsonify({"error": "Chưa có Anthropic key. Nạp sk-ant-... tại 🔑 Key AI hoặc cấu hình ANTHROPIC_API_KEY trên Render."}), 400
    system_prompt = (
        "Bạn là chuyên gia LaTeX cho sách giáo khoa Vật lý/Toán THPT Việt Nam.\n"
        "CHỈ trả về nội dung đã sửa, KHÔNG giải thích, KHÔNG thêm text thừa.\n\n"
        "Các lỗi cần sửa:\n"
        "1. {{X}_{n}} → X_{n} · {>}{<}{=} → ><= (bỏ {} thừa từ Word)\n"
        "2. mathrm/mathbf/text thiếu \\ → thêm \\\n"
        r"3. \(\begin{aligned) → $$\begin{aligned} và \end{aligned}.\) → \end{aligned}.$$" + "\n"
        r"4. \newline trong aligned/array/cases → \\" + "\n"
        r"5. $\cdot$ $\Rightarrow$ $\to$ đứng rời → bỏ $ bao" + "\n"
        "6. Giữ nguyên tiếng Việt và xuống dòng\n"
        "7. Nếu không có lỗi, trả về NGUYÊN VĂN không thay đổi"
    )
    try:
        import urllib.request as _ur
        payload_bytes = json.dumps({
            "model": "claude-haiku-4-5-20251001",
            "max_tokens": 800,
            "system": system_prompt,
            "messages": [{"role": "user", "content": text}],
        }).encode("utf-8")
        req = _ur.Request(
            "https://api.anthropic.com/v1/messages",
            data=payload_bytes,
            headers={
                "Content-Type": "application/json",
                "x-api-key": api_key,
                "anthropic-version": "2023-06-01",
            },
            method="POST",
        )
        with _ur.urlopen(req, timeout=30) as resp:
            resp_body = json.loads(resp.read().decode("utf-8"))
        fixed = "".join(
            b.get("text", "") for b in resp_body.get("content", []) if b.get("type") == "text"
        ).strip()
        if not fixed:
            return jsonify({"ok": True, "text": text, "changed": False})
        return jsonify({"ok": True, "text": fixed, "changed": fixed != text})
    except Exception as e:
        err = str(e)
        # Anthropic trả lỗi trong HTTPError body
        try:
            import urllib.error as _ue
            if isinstance(e, _ue.HTTPError):
                err_body = json.loads(e.read().decode("utf-8"))
                err = err_body.get("error", {}).get("message", err)
        except Exception:
            pass
        return jsonify({"error": f"Claude API lỗi: {err}"}), 500



