@app.route("/api/ai/detect-dangbaitap-bulk", methods=["POST"])
def api_ai_detect_dangbaitap_bulk():
    """ADMIN: GPT gợi ý DangBaiTap cho nhiều câu đang xem. Không lưu Sheet."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được dùng GPT gợi ý Dạng bài tập hàng loạt."}), 403
    body = request.get_json(silent=True) or {}
    raw_qs = body.get("questions") or []
    lesson_dbt_context = body.get("lesson_dbt_context") or {}
    if not isinstance(lesson_dbt_context, dict):
        lesson_dbt_context = {}
    admin_dbt_guide = clean(body.get("admin_dbt_guide") or "")
    admin_dbt_types_by_scope = _normalize_admin_dbt_types_by_scope(
        body.get("admin_dbt_types_by_scope") or {}
    )
    if not isinstance(raw_qs, list) or not raw_qs:
        return jsonify({"error": "Chưa có danh sách câu để gợi ý."}), 400
    if len(raw_qs) > 12:
        return jsonify({"error": "Tối đa 12 câu/lần (Render timeout). App tự gọi nhiều lô — không gửi >12 câu một request."}), 400
    qs: List[Dict[str, Any]] = []
    meta_rows: List[Dict[str, Any]] = []
    for i, raw in enumerate(raw_qs):
        if not isinstance(raw, dict):
            continue
        q: Dict[str, Any] = {}
        for f in QUESTION_FIELDS:
            q[f] = clean(raw.get(f, ""))
        q["Dang"] = effective_dang(q)
        qs.append(q)
        try:
            idx = int(raw.get("index", i))
        except Exception:
            idx = i
        meta_rows.append({"index": idx, "row": clean(raw.get("row") or raw.get("_row") or ""), "ID": clean(raw.get("ID", ""))})
    if not qs:
        return jsonify({"error": "Không đọc được câu hỏi hợp lệ."}), 400
    try:
        st = get_store()
        st.ensure_questions_loaded()
        force, allow = admin_ai_body_params(body)
        extra_ant_key = clean(body.get("anthropic_key", ""))
        meta = admin_gpt_classify_dangbaitap_bulk(
            qs, st, lesson_dbt_context=lesson_dbt_context,
            admin_dbt_guide=admin_dbt_guide,
            admin_dbt_types_by_scope=admin_dbt_types_by_scope,
            force_provider=force, allow_gpt_fallback=allow,
            extra_anthropic_key=extra_ant_key,
        )
        lesson_canonical = _lesson_dbt_canonical_from_questions(qs, DBT_MAX_TYPES_PER_LESSON)
        items: List[Dict[str, Any]] = []
        detected = 0
        for q, m, raw in zip(qs, meta_rows, raw_qs):
            dbt = clean(q.get("_AiDangBaiTap") or "")
            if dbt:
                detected += 1
            preview = clean(q.get("CauHoi", ""))
            if len(preview) > 160:
                preview = preview[:157].rstrip() + "…"
            sk = _lesson_scope_key(q)
            scoped = lesson_canonical.get(sk) or []
            if not scoped:
                try:
                    scoped, _ = _scoped_dangbaitap_suggestions(st, q, limit=DBT_MAX_TYPES_PER_LESSON)
                except Exception:
                    scoped = []
            items.append({
                "index": m.get("index"),
                "row": m.get("row"),
                "ID": m.get("ID") or clean(q.get("ID", "")),
                "Mon": clean(q.get("Mon", "")),
                "Chuong": clean(q.get("Chuong", "")),
                "BaiHoc": clean(q.get("BaiHoc", "")),
                "Dang": q.get("Dang", ""),
                "DangBaiTap": dbt,
                "ai_dbt": dbt,
                "current_dbt": clean(raw.get("DangBaiTap", "")),
                "matched_existing": bool(q.get("_AiMatchedExisting")),
                "reason": clean(q.get("_AiReason", "")),
                "preview": preview,
                "suggestions": scoped[:DBT_MAX_TYPES_PER_LESSON],
            })
        cons = meta.get("dbt_lesson_consolidation") or {}
        ai_prov = meta.get("ai_provider", "GEMINI")
        return jsonify({
            "ok": True,
            "items": items,
            "detected": detected,
            "total": len(items),
            "ai_provider": ai_prov,
            "provider_used": ai_prov,
            "ai_model": meta.get("ai_model", ""),
            "warning": clean(meta.get("ai_dbt_error", "")),
            "dbt_merged": int(cons.get("merged") or 0),
            "lesson_dbt_context": lesson_canonical,
        })
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)
    except Exception as e:
        return jsonify({"error": str(e), "ok": False}), 400


